(async () => {
 const sleep=ms=>new Promise(r=>setTimeout(r,ms));
 const wait=async(fn,label,limit=1200)=>{for(let i=0;i<limit;i++){if(fn())return;await sleep(50);}throw Error('Timeout: '+label);};
 const frame=()=>new Promise(requestAnimationFrame);
 const report={engine:navigator.userAgent,scenarios:[],errors:[]};
 let active, key, timer, originalDispatch;
 try {
  await wait(()=>window._appReady&&document.querySelector('.file-tree-item[data-path="Welcome.md"] .file-tree-node'),'startup');
  document.querySelector('.file-tree-item[data-path="Welcome.md"] .file-tree-node').click();
  await wait(()=>document.querySelector('.cm-content')?.cmTile?.root?.view?.state?.doc?.lines>23&&document.hasFocus(),'owned native focus');await sleep(1200);
  let view=document.querySelector('.cm-content').cmTile.root.view;
  document.getElementById('writing-lenses-toggle').click();await sleep(300);
  const inputs=()=>[...document.querySelectorAll('#writing-lenses-panel input[type="checkbox"]')];
  await wait(()=>inputs().length===5,'five lenses');
  const sourceFor=diagrams=>Array.from({length:560},(_,i)=>`Paragraph ${i}. The report was written in order to help the team utilize ordinary words for readers. We can review this carefully.`+(diagrams&&i%28===0?'\n\n```mermaid\nflowchart LR\nA[Read the draft] --> B[Discuss the details] --> C[Revise the note]\n```':'')).join('\n\n');
  const onKey=event=>{
   if(!active||!event.isTrusted||event.key.length!==1)return;
   key={key:event.key,trusted:event.isTrusted,epochMs:Date.now(),start:performance.now(),dispatchMs:[],inputMs:null,frameMs:null,secondFrameMs:null};active.keys.push(key);
   const current=key;requestAnimationFrame(()=>{current.frameMs=performance.now()-current.start;requestAnimationFrame(()=>{current.secondFrameMs=performance.now()-current.start;});});
  };
  document.addEventListener('keydown',onKey,true);
  document.addEventListener('input',event=>{if(active&&key&&event.target===view.contentDOM){const current=key;queueMicrotask(()=>{current.inputMs=performance.now()-current.start;});}},true);
  let tick=performance.now();timer=setInterval(()=>{const now=performance.now();if(active)active.timerGapsMs.push(now-tick);tick=now;},16);
  const cases=[{lenses:false,diagrams:false},{lenses:true,diagrams:false},{lenses:true,diagrams:true},{lenses:false,diagrams:true},{lenses:false,diagrams:true},{lenses:true,diagrams:true},{lenses:true,diagrams:false},{lenses:false,diagrams:false}];
  cases.push(...cases.slice(0,4).map(row=>({...row,vim:true})));
  for(const [index,scenario] of cases.entries()) {
   if(scenario.vim&&!view.dom.classList.contains('vim-insert')) {
    document.getElementById('topbar-settings').click();await wait(()=>document.getElementById('vim-toggle'),'Vim setting');await sleep(1000);
    if(!document.getElementById('vim-toggle').checked)document.getElementById('vim-toggle').click();await sleep(250);
    document.querySelector('.file-tree-item[data-path="Welcome.md"] .file-tree-node').click();await sleep(400);view=document.querySelector('.cm-content').cmTile.root.view;view.focus();
    view.contentDOM.dispatchEvent(new KeyboardEvent('keydown',{key:'i',code:'KeyI',bubbles:true,cancelable:true}));await frame();
    if(!view.dom.classList.contains('vim-insert'))throw Error('Vim Insert mode not active');
   }
   for(let i=0;i<5;i++) {
    await wait(()=>!inputs()[i].disabled,'lens control ready');
    if(inputs()[i].checked!==scenario.lenses){inputs()[i].click();await sleep(200);}
   }
   const source=sourceFor(scenario.diagrams);
   view.dispatch({changes:{from:0,to:view.state.doc.length,insert:source},selection:{anchor:14}});view.focus();await sleep(2000);
   const settled=performance.now();
   await wait(()=>!document.querySelector('.writing-results')?.hasAttribute('aria-busy'),'analysis settle');
   await sleep(400);await frame();
   if(scenario.diagrams&&!view.dom.querySelector('[data-source-footprint="mermaid"] svg'))throw Error('No rendered Mermaid in diagram workload');
   if(inputs().filter(input=>input.checked).length!==(scenario.lenses?5:0))throw Error('Wrong lens selection');
   const beginLength=view.state.doc.length;
   active={index,...scenario,words:source.split(/\s+/).length,sourceLength:source.length,diagramWidgets:view.dom.querySelectorAll('[data-source-footprint="mermaid"] svg').length,reviewWaitMs:performance.now()-settled,keys:[],timerGapsMs:[],selectedLenses:inputs().filter(input=>input.checked).map(input=>input.value),vimClass:view.dom.className,initialFindings:document.querySelector('.writing-results')?.textContent.slice(0,120)};
   report.scenarios.push(active);const record=active;
   originalDispatch=view.dispatch;view.dispatch=function(...args){const start=performance.now();try{return originalDispatch.apply(this,args);}finally{if(key&&active===record)key.dispatchMs.push(performance.now()-start);}};
   await window.go.desktop.App.CreateFile(`.config/typing-ready-${index}.json`,JSON.stringify({index,keys:70}));
   await wait(()=>record.keys.length>=70,'native typing '+index);await sleep(1400);
   record.inserted=view.state.doc.length-beginLength;record.focused=view.hasFocus;
   active=null;key=null;view.dispatch=originalDispatch;
  }
 }catch(error){report.errors.push(error.stack||error.message);}
 clearInterval(timer);
 await window.go.desktop.App.CreateFile('.config/typing-report.json',JSON.stringify(report,null,2));
})();
